"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

import { CircleCheck, CircleX, Info, LoaderCircle, TriangleAlert } from "lucide-react";
import "./feedback.css";

export type FeedbackVariant = "neutral" | "success" | "warning" | "error";

const icons = {
  neutral: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleX,
};

export function FeedbackIcon({
  variant,
  loading = false,
}: {
  variant: FeedbackVariant;
  loading?: boolean;
}) {
  const Icon = loading ? LoaderCircle : icons[variant];
  return (
    <span data-slot="feedback-icon" aria-hidden="true">
      <span data-slot="feedback-symbol" key={loading ? "loading" : variant}>
        <Icon data-slot={loading ? "loading-indicator" : undefined} />
      </span>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as Primitive from "@radix-ui/react-toast";
import { X } from "lucide-react";
import {
  useId,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from "react";
import { Button, type ButtonProps } from "./button";
import { FeedbackIcon, type FeedbackVariant } from "./feedback";
import { cn } from "./lib/cn";
import "./shared/alert.css";
import "./toast.css";

export type ToastProps = Omit<
  ComponentProps<typeof Primitive.Root>,
  "title" | "children" | "asChild"
> & {
  title: ReactNode;
  variant?: FeedbackVariant;
  loading?: boolean;
  children?: ReactNode;
  action?: {
    label: string;
    altText: string;
    onClick: ButtonProps["onClick"];
    disabled?: boolean;
  };
};

export function ToastProvider({
  duration = 6000,
  label = "Notification",
  swipeDirection = "right",
  ...props
}: ComponentProps<typeof Primitive.Provider>) {
  return (
    <Primitive.Provider
      duration={duration}
      label={label}
      swipeDirection={swipeDirection}
      {...props}
    />
  );
}

export function Toast({
  title,
  variant = "neutral",
  loading = false,
  children,
  action,
  className,
  style,
  duration,
  ...props
}: ToastProps) {
  const titleId = useId();
  const descriptionId = useId();
  const [content, setContent] = useState<HTMLDivElement | null>(null);
  const [height, setHeight] = useState<number>();
  const [instantLayout, setInstantLayout] = useState(false);
  const previousMessage = useRef<{ node: HTMLDivElement; text: string } | null>(null);
  const announcement = useRef<HTMLSpanElement>(null);
  const messageKey = loading ? "loading" : variant;
  useLayoutEffect(() => {
    if (!content) return;
    let previousWidth: number | undefined;
    let previousDensity: string | undefined;
    let previousHeight: number | undefined;
    const measure = () => {
      const bounds = content.getBoundingClientRect();
      const density = getComputedStyle(content).getPropertyValue("--control-height");
      if (previousWidth !== undefined && (previousWidth !== bounds.width || previousDensity !== density)) {
        setInstantLayout(true);
      } else if (previousHeight !== bounds.height) {
        setInstantLayout(false);
      }
      setHeight(bounds.height);
      previousWidth = bounds.width;
      previousDensity = density;
      previousHeight = bounds.height;
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(content);
    return () => observer.disconnect();
  }, [content]);
  useEffect(() => {
    if (!content) {
      previousMessage.current = null;
      if (announcement.current) announcement.current.textContent = "";
      return;
    }
    const text = [
      content.querySelector('[data-slot="feedback-title"]')?.textContent,
      content.querySelector('[data-slot="feedback-description"]')?.textContent,
    ].filter(Boolean).join(" ");
    if (
      previousMessage.current?.node === content &&
      previousMessage.current.text !== text &&
      content.parentElement?.dataset.state === "open" &&
      announcement.current
    ) {
      announcement.current.textContent = text;
    }
    previousMessage.current = { node: content, text };
  }, [content, title, children]);

  return (
    <>
    <Primitive.Root
      data-slot="toast"
      data-variant={loading ? "neutral" : variant}
      data-layout={instantLayout ? "instant" : undefined}
      aria-busy={loading || undefined}
      // Errors stay until dismissed; pending work never times out mid-way.
      duration={duration ?? (variant === "error" || loading ? Infinity : undefined)}
      aria-labelledby={titleId}
      aria-describedby={children != null ? descriptionId : undefined}
      className={cn(
        "block min-w-0 shrink-0 rounded-surface bg-elevated text-sm text-foreground shadow-feedback outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring [overflow-wrap:anywhere]",
        className,
      )}
      style={{
        touchAction: "var(--caliper-toast-touch-action, none)",
        "--caliper-toast-block-size": height === undefined ? undefined : `${height}px`,
        ...style,
      } as CSSProperties}
      {...props}
    >
      <div
        ref={setContent}
        data-slot="toast-content"
        className="grid min-w-0 grid-cols-[2rem_minmax(0,1fr)_auto] items-start gap-3"
      >
        <FeedbackIcon variant={variant} loading={loading} />
        <div data-slot="feedback-copy" className="min-w-0 pt-1">
          <Primitive.Title id={titleId} data-slot="feedback-title" className="font-semibold leading-5">
            <span key={messageKey} data-slot="feedback-message">{title}</span>
          </Primitive.Title>
          {children != null && (
            <Primitive.Description
              id={descriptionId}
              data-slot="feedback-description"
              className="mt-1 text-sm leading-5 text-muted-foreground"
            >
              <span key={messageKey} data-slot="feedback-message">{children}</span>
            </Primitive.Description>
          )}
          {action && (
            <div data-slot="feedback-action" className="mt-3">
              <Primitive.Action asChild altText={action.altText}>
                <Button
                  variant="secondary"
                  size="sm"
                  className="h-auto min-h-8 max-w-full py-1.5 whitespace-normal text-left"
                  disabled={action.disabled}
                  onClick={action.onClick}
                >
                  {action.label}
                </Button>
              </Primitive.Action>
            </div>
          )}
        </div>
        <Primitive.Close asChild>
          <Button
            variant="ghost"
            size="icon"
            className="-mt-1 -mr-1"
            aria-label="Dismiss notification"
          >
            <X aria-hidden="true" />
          </Button>
        </Primitive.Close>
      </div>
    </Primitive.Root>
    <span ref={announcement} data-slot="toast-update-announcement" className="sr-only" aria-live="polite" aria-atomic="true" />
    </>
  );
}

export function ToastStack({
  className,
  label = "Notifications ({hotkey})",
  ...props
}: ComponentProps<typeof Primitive.Viewport>) {
  return (
    <Primitive.Viewport
      data-slot="toast-stack"
      label={label}
      className={cn(
        "fixed right-0 bottom-0 z-[60] m-0 flex max-h-[100dvh] w-full max-w-[26rem] list-none flex-col-reverse overflow-y-auto p-4 outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
        className,
      )}
      {...props}
    />
  );
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--raised-press);
    --b-bg-hover: var(--raised-press);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* feedback.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="feedback-icon"] {
    display: flex;
    width: 2rem;
    height: 2rem;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-surface);
    background: var(--muted);
    color: var(--muted-foreground);
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
  }
  [data-slot="feedback-symbol"] {
    display: flex;
    animation: caliper-feedback-symbol-enter var(--duration-normal) var(--ease-out);
  }
  [data-slot="feedback-icon"] svg {
    width: 1rem;
    height: 1rem;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="feedback-icon"] {
      transition: none;
      transform: none !important;
    }
    [data-slot="feedback-symbol"] {
      animation: none;
    }
  }
}

/* Shared by alert.tsx, toast.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="feedback-message"] {
    display: block;
    animation: caliper-fade-in var(--duration-normal) var(--ease-out);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="success"]
    [data-slot="feedback-icon"] {
    background: var(--success-subtle);
    color: var(--success);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="warning"]
    [data-slot="feedback-icon"] {
    background: var(--warning-subtle);
    color: var(--warning);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="error"]
    [data-slot="feedback-icon"] {
    background: var(--destructive-subtle);
    color: var(--destructive);
  }
  @container (max-width: 22rem) {
    [data-slot="feedback-copy"] {
      display: contents;
    }
    [data-slot="feedback-title"] {
      grid-column: 2;
      grid-row: 1;
      min-width: 0;
      padding-top: 0.25rem;
    }
    [data-slot="feedback-description"],
    [data-slot="feedback-action"] {
      grid-column: 1 / -1;
      margin-top: 0;
    }
    [data-slot="feedback-description"] {
      grid-row: 2;
    }
    [data-slot="feedback-action"] {
      grid-row: 3;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="feedback-message"] {
      animation: none;
    }
  }
}

/* toast.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="toast"] {
    --caliper-toast-touch-action: pan-y;
    --caliper-toast-exit-x: 100%;
    --caliper-toast-exit-y: 0px;
    margin-block-start: 0.5rem;
    container-type: inline-size;
    block-size: var(--caliper-toast-block-size, 0px);
    overflow: clip;
    transition:
      block-size var(--duration-normal) var(--ease-out),
      margin-block-start var(--duration-normal) var(--ease-out);
  }
  [data-slot="toast-content"] {
    min-width: 0;
    border-radius: inherit;
    border: 1px solid var(--border);
    padding: 1rem;
  }
  [data-slot="toast"][data-layout="instant"] {
    transition: none;
  }
  [data-slot="toast"][data-state="open"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }
  [data-slot="toast"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
    block-size: 0;
    margin-block-start: 0;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-in);
  }
  @starting-style {
    [data-slot="toast"][data-state="open"] {
      block-size: 0;
      margin-block-start: 0;
    }
  }
  @container (max-width: 22rem) {
    [data-slot="toast-content"] > [data-slot="button"] {
      grid-column: 3;
      grid-row: 1;
    }
  }
  [data-slot="toast"][data-swipe-direction="left"] {
    --caliper-toast-exit-x: -100%;
  }
  [data-slot="toast"][data-swipe-direction="up"],
  [data-slot="toast"][data-swipe-direction="down"] {
    --caliper-toast-touch-action: pan-x;
    --caliper-toast-exit-x: 0px;
  }
  [data-slot="toast"][data-swipe-direction="up"] {
    --caliper-toast-exit-y: -100%;
  }
  [data-slot="toast"][data-swipe-direction="down"] {
    --caliper-toast-exit-y: 100%;
  }
  [data-slot="toast"][data-state="open"]:is(
      [data-swipe="start"],
      [data-swipe="move"],
      [data-swipe="cancel"]
    ) {
    animation: none;
  }
  [data-slot="toast"][data-swipe="move"] {
    transform: translate(
      var(--radix-toast-swipe-move-x, 0px),
      var(--radix-toast-swipe-move-y, 0px)
    );
  }
  [data-slot="toast"][data-swipe="cancel"] {
    transform: translate(0, 0);
    transition: transform var(--duration-fast) var(--ease-out);
  }
  [data-slot="toast"][data-state="closed"][data-swipe="end"] {
    animation: caliper-toast-swipe-out var(--duration-fast) var(--ease-in) forwards;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="toast"][data-state="open"] {
      animation: none;
    }
    [data-slot="toast"] {
      animation: none;
    }
    [data-slot="toast"] {
      transition: none;
      transform: none !important;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="toast"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
    [data-slot="toast"][data-state="closed"][data-swipe="end"] {
      animation: caliper-toast-swipe-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}

[data-slot="toast"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}

@keyframes caliper-toast-swipe-out {
  from {
    opacity: 1;
    transform: translate(
      var(--radix-toast-swipe-end-x, 0px),
      var(--radix-toast-swipe-end-y, 0px)
    );
  }
  to {
    opacity: 0;
    transform: translate(var(--caliper-toast-exit-x), var(--caliper-toast-exit-y));
  }
}
